select from basket_standing_rank_reason where is_delete = 0 and standing_id in
#{id}
order by standing_id asc, priority_no asc, id asc

mapper.update:
update basket_standing_rank_reason r
inner join basket_standing s on s.id = r.standing_id
set r.is_delete = 1, r.update_time = now()
where s.division_id = #{divisionId}
  and s.stage_id = #{stageId}
  and s.group_scope_key = #{groupScopeKey}
  and s.is_delete = 0
  and r.is_delete = 0

